def request(prompt, task, cfg):
    n1 = c_wire.mode(task=task, cfg=cfg)
    n2 = c_wire.payload(prompt=prompt, task=task, mode=n1, cfg=cfg)
    return n2


def response(provider, raw):
    n1 = c_wire.read(provider=provider, raw=_v.dump(raw))
    return n1


def cost(answer, operator):
    n1 = c_price.cost(answer=answer, operator=operator)
    return n1
